  const text=String(value); let ns=small?58:72, nm=measure(text,ns,600,numberFamily);
  while((nm.width>maxWidth||nm.ascent+nm.descent>labelTop-gap-y-pad)&&ns>8)nm=measure(text,--ns,600,numberFamily);
  const ny=y+pad+nm.ascent;
  c.font=nm.font; c.fillStyle=ink; c.fillText(text,x+w/2,ny);
